/** One row per rank: the name and colour members see, and the Flarum group that holds it. */
function ranks(stream) {
  let saved = null;
  try {
    saved = JSON.parse(stream() || 'null');
  } catch {
    saved = null;
  }
  const value = rank => ({
    ...(saved?.[rank] || {}),
    group: saved ? saved[rank]?.group ?? null : DEFAULT_GROUPS[rank] ?? null
  });
  const set = (rank, field, v) => {
    const next = {};
    for (const [k] of RANKS) next[k] = value(k);
    next[rank] = {
      ...next[rank],
      [field]: v === '' ? null : v
    };
    stream(JSON.stringify(next));
  };
  const groups = app.store.all('groups').filter(g => !['2', '3'].includes(g.id()));
  return m("div", {
    className: "Form-group HangoutAdmin-ranks"
  }, m("label", null, t('settings.ranks')), m("div", {
    className: "helpText"
  }, t('settings.ranks_help')), m("table", {
    className: "HangoutAdmin-table"
  }, m("thead", null, m("tr", null, m("th", null, t('settings.rank')), m("th", null, t('settings.rank_name')), m("th", null, t('settings.rank_color')), m("th", null, t('settings.rank_group')))), m("tbody", null, RANKS.map(([rank, name, color]) => {
    const v = value(rank);
    return m("tr", null, m("td", null, t('ranks.' + rank)), m("td", null, m("input", {
      className: "FormControl",
      "aria-label": ts('settings.rank_name'),
      placeholder: name,
      value: v.name || '',
      maxlength: 40,
      oninput: e => set(rank, 'name', e.target.value)
    })), m("td", null, m("input", {
      className: "FormControl HangoutAdmin-color",
      type: "color",
      "aria-label": ts('settings.rank_color'),
      value: v.color || color,
      oninput: e => set(rank, 'color', e.target.value)
    })), m("td", null, rank === 'mortal' ? m("span", {
      className: "helpText"
    }, t('settings.mortal_group')) : m("select", {
      className: "FormControl",
      "aria-label": ts('settings.rank_group'),
      value: v.group ? 'g' + v.group : '',
      onchange: e => set(rank, 'group', e.target.value.replace(/^g/, ''))
    }, m("option", {
      value: ""
    }, t('settings.no_group')), groups.map(g => m("option", {
      value: 'g' + g.id()
    }, g.namePlural())))));
  }))));
}